package GeneratedModel {
  private import ScalarValues::*;
  part def Controller {
    in attribute io_0 : Real;
    in attribute io_1 : Real;
    in attribute io_3 : Integer;
    attribute elapsedTotal : Integer := 0;
    attribute exceeded : Boolean := false;
    perform action tick {
      first start;
      then assign elapsedTotal := elapsedTotal + io_3;
      then assign exceeded := io_0 >= 500.0 or io_1 >= 50.0;
      then if elapsedTotal >= 1000 {
        first start;
        then assign elapsedTotal := elapsedTotal - 1000;
      }
    }
    out attribute io_2 : Boolean = exceeded;
    out attribute serial_0_trigger : Boolean = elapsedTotal == 0;
    out attribute serial_0_value_0 : Real = io_0;
    out attribute serial_0_value_1 : Real = io_1;
    out attribute serial_1_trigger : Boolean = exceeded and (elapsedTotal == 0);
    out attribute serial_1_value_0 : Boolean = exceeded;
  }
  part system : Controller;
}
